(function () {
  "use strict";

  async function api(path, opts) {
    var res = await fetch(path, Object.assign({ headers: { "Content-Type": "application/json" } }, opts));
    var data = null;
    try { data = await res.json(); } catch (e) { /* non-JSON */ }
    if (!res.ok) {
      var detail = data && data.detail;
      var message = detail && typeof detail === "object" ? detail.detail : detail;
      var error = new Error(message || (data && data.error) || res.status + " " + res.statusText);
      error.code = detail && typeof detail === "object" ? detail.code : (data && data.code);
      error.status = res.status;
      error.data = data;
      throw error;
    }
    return data;
  }

  function esc(s) {
    var d = document.createElement("div");
    d.textContent = s == null ? "" : String(s);
    return d.innerHTML;
  }

  var ORIGIN_BLURBS = {
    human: "Modelled by a person. No generative AI produced the geometry.",
    ai_assisted: "A person directed the design; AI produced part of the work.",
    ai_generated: "Predominantly generated by AI from a prompt or reference."
  };
  var ORIGIN_LABELS = { human: "Human-made", ai_assisted: "AI-assisted", ai_generated: "AI-generated" };
  var ROUTES = ["overview", "listings", "new", "imports", "payouts", "settings"];
  var STAGES = ["files", "essentials-a", "essentials-b", "price", "origin", "attestation-a", "attestation-b", "review"];
  var STAGE_GROUPS = {
    files: "files",
    "essentials-a": "essentials",
    "essentials-b": "essentials",
    price: "price",
    origin: "origin",
    "attestation-a": "origin",
    "attestation-b": "origin",
    review: "review"
  };

  var state = {
    meta: null,
    overview: null,
    seller: null,
    isSeller: false,
    route: "overview",
    listings: [],
    listingStatus: "",
    listingCursor: null,
    sources: [],
    activeImport: null,
    connect: null,
    earnings: null,
    composer: null,
    handleTimer: null,
    handleSequence: 0
  };

  function byId(id) { return document.getElementById(id); }
  function show(el, yes) { if (el) { el.classList.toggle("hidden", !yes); } }
  function int(value) { var n = Number(value); return Number.isFinite(n) ? Math.trunc(n) : 0; }
  function formatInt(value) { return int(value).toLocaleString(); }
  function formatCash(cents) { return "$" + (int(cents) / 100).toFixed(2); }
  function formatBytes(bytes) {
    var n = int(bytes);
    if (n < 1024) { return n + " B"; }
    if (n < 1024 * 1024) { return (n / 1024).toFixed(1) + " KiB"; }
    if (n < 1024 * 1024 * 1024) { return (n / (1024 * 1024)).toFixed(1) + " MiB"; }
    return (n / (1024 * 1024 * 1024)).toFixed(1) + " GiB";
  }
  function statusLabel(value) { return String(value || "none").replace(/_/g, " "); }
  function safeHttpUrl(value) {
    try {
      var url = new URL(String(value || ""), window.location.origin);
      return url.protocol === "http:" || url.protocol === "https:" ? url.href : "";
    } catch (e) { return ""; }
  }
  function setSubmitState(el, message, kind) {
    if (!el) { return; }
    el.textContent = message || "";
    el.classList.toggle("is-error", kind === "error");
    el.classList.toggle("is-ok", kind === "ok");
  }
  function notice(message, kind) {
    var el = byId("global-notice");
    el.textContent = message || "";
    el.className = "st-notice" + (kind ? " is-" + kind : "");
    show(el, !!message);
  }
  function jsonOptions(method, payload) {
    return { method: method, body: JSON.stringify(payload == null ? {} : payload) };
  }
  function formValues(form) {
    var out = {};
    new FormData(form).forEach(function (value, key) { out[key] = String(value).trim(); });
    return out;
  }

  function activeStages() {
    return STAGES.filter(function (name) {
      return state.composer.data.origin === "human" || (name !== "attestation-a" && name !== "attestation-b");
    });
  }

  function freshComposer() {
    return {
      step: 0,
      id: null,
      status: "draft",
      data: {
        title: "",
        summary: "",
        category_id: "",
        tags: "",
        description: "",
        license_id: "",
        pricing_kind: "free",
        price_cents: 0,
        price_credits: 0,
        tips_enabled: false,
        origin: "",
        origin_note: "",
        process_note: "",
        tools: "",
        hours: "",
        ai_tools_note: ""
      },
      files: [],
      assets: [],
      versions: [],
      creditOverridden: false,
      busy: false
    };
  }

  function currentStage() { return activeStages()[state.composer.step] || "review"; }

  function routeFromHash() {
    var route = (window.location.hash || "#overview").slice(1).split("?")[0];
    return ROUTES.indexOf(route) >= 0 ? route : "overview";
  }

  function applyRoute() {
    var route = routeFromHash();
    if (!state.isSeller && route !== "overview") {
      window.location.hash = "overview";
      notice("Open a seller profile before using Seller Studio.", "warn");
      return;
    }
    state.route = route;
    document.querySelectorAll("[data-route]").forEach(function (section) {
      section.classList.toggle("hidden", section.getAttribute("data-route") !== route);
    });
    document.querySelectorAll("[data-route-link]").forEach(function (link) {
      var active = link.getAttribute("data-route-link") === route;
      link.classList.toggle("is-active", active);
      if (active) { link.setAttribute("aria-current", "page"); } else { link.removeAttribute("aria-current"); }
    });
    if (route === "listings") { loadListings(false); }
    if (route === "new") {
      if (!state.composer) { state.composer = freshComposer(); }
      renderComposer();
    }
    if (route === "imports") { loadSources(); }
    if (route === "payouts") { loadPayouts(); }
    if (route === "settings") { loadSettings(); }
    window.scrollTo({ top: 0, behavior: "instant" });
  }

  function renderNoSeller() {
    state.isSeller = false;
    show(byId("overview-loading"), false);
    show(byId("enrolment-panel"), true);
    show(byId("overview-dashboard"), false);
    document.querySelectorAll(".st-seller-only").forEach(function (el) { show(el, false); });
    byId("account-label").textContent = "Seller profile not opened";
  }

  function statCard(label, value) {
    if (!int(value)) { return ""; }
    return '<div class="st-stat"><strong>' + formatInt(value) + "</strong><span>" + esc(label) + "</span></div>";
  }

  function compactListingRow(listing) {
    return '<div class="st-listing-row"><div class="st-listing-main"><h3>' + esc(listing.title) + "</h3>" +
      (listing.summary ? "<p>" + esc(listing.summary) + "</p>" : "") +
      '<div class="st-listing-meta"><span class="st-status is-' + esc(listing.status) + '">' + esc(statusLabel(listing.status)) + "</span>" +
      '<span class="st-status is-' + esc(listing.attestation_status || "none") + '">Attestation: ' + esc(statusLabel(listing.attestation_status || "none")) + "</span></div></div></div>";
  }

  function renderOverview(data) {
    state.overview = data;
    state.seller = data.seller || null;
    state.isSeller = !!state.seller;
    show(byId("overview-loading"), false);
    if (!state.isSeller) { renderNoSeller(); return; }
    show(byId("enrolment-panel"), false);
    show(byId("overview-dashboard"), true);
    document.querySelectorAll(".st-seller-only").forEach(function (el) { show(el, true); });
    byId("account-label").textContent = state.seller.display_name || state.seller.handle;

    var stats = data.stats || {};
    byId("overview-stats").innerHTML = [
      statCard("Listings", stats.listings),
      statCard("Published", stats.published),
      statCard("Drafts", stats.drafts),
      statCard("In review", stats.in_review),
      statCard("Downloads", stats.downloads),
      statCard("Sales", stats.sales),
      statCard("Favorites", stats.favorites)
    ].join("");

    var recent = data.recent_listings || [];
    byId("recent-listings").innerHTML = recent.length ? recent.map(compactListingRow).join("") :
      '<div class="mk-empty st-empty"><h3>No listings yet</h3><p>Create your first listing or import work you already published elsewhere.</p></div>';

    var actions = [];
    if (!int(stats.listings)) {
      actions.push('<a class="st-action-card" href="#new"><strong>Create your first listing</strong><span>Add files, licensing, and an honest provenance disclosure.</span></a>');
      actions.push('<a class="st-action-card" href="#imports"><strong>Import existing work</strong><span>Prefill a draft from a supported model site.</span></a>');
    } else {
      if (int(stats.drafts)) { actions.push('<a class="st-action-card" href="#listings"><strong>Finish a draft</strong><span>Review staged models and publish when ready.</span></a>'); }
      actions.push('<a class="st-action-card" href="#payouts"><strong>Review earnings</strong><span>Connect payouts and see your cash and credit net.</span></a>');
    }
    byId("next-actions").innerHTML = actions.join("") || '<div class="mk-empty st-empty"><p>Your catalog is current.</p></div>';
  }

  async function loadOverview() {
    try {
      var data = await api("/api/studio/overview");
      renderOverview(data);
    } catch (error) {
      show(byId("overview-loading"), false);
      if (error.code === "not_a_seller") { renderNoSeller(); return; }
      notice(error.message, "error");
    }
  }

  function scheduleHandleCheck(input, feedback) {
    window.clearTimeout(state.handleTimer);
    var raw = input.value.trim();
    var validShape = /^[a-z0-9][a-z0-9_-]{1,38}$/.test(raw);
    input.setAttribute("aria-invalid", validShape ? "false" : "true");
    feedback.className = validShape ? "" : "is-error";
    feedback.textContent = validShape ? "Checking availability…" : "Use 2–39 lowercase letters, numbers, underscores, or hyphens.";
    input.dataset.available = "";
    if (!validShape) { return; }
    var sequence = ++state.handleSequence;
    state.handleTimer = window.setTimeout(async function () {
      try {
        var result = await api("/api/marketplace/handle-check?handle=" + encodeURIComponent(raw));
        if (sequence !== state.handleSequence || input.value.trim() !== raw) { return; }
        input.dataset.available = result.available ? "true" : "false";
        input.setAttribute("aria-invalid", result.available ? "false" : "true");
        feedback.className = result.available ? "is-ok" : "is-error";
        if (result.available) {
          feedback.textContent = "Available as @" + result.handle + ". Availability is confirmed again when you submit.";
        } else {
          var reason = result.reason === "reserved" ? "That handle is reserved." : "That handle is already taken.";
          feedback.textContent = reason + (result.suggestion ? " Try @" + result.suggestion + "." : "");
        }
      } catch (error) {
        if (sequence !== state.handleSequence) { return; }
        input.dataset.available = "";
        feedback.className = "is-error";
        feedback.textContent = "Availability could not be checked. Try again before submitting.";
      }
    }, 320);
  }

  async function ensureHandleAvailable(input, feedback) {
    if (input.dataset.available === "true") { return true; }
    window.clearTimeout(state.handleTimer);
    var result = await api("/api/marketplace/handle-check?handle=" + encodeURIComponent(input.value.trim()));
    input.dataset.available = result.available ? "true" : "false";
    input.setAttribute("aria-invalid", result.available ? "false" : "true");
    feedback.className = result.available ? "is-ok" : "is-error";
    feedback.textContent = result.available ? "Available as @" + result.handle + "." :
      (result.reason === "reserved" ? "That handle is reserved." : "That handle is already taken.") + (result.suggestion ? " Try @" + result.suggestion + "." : "");
    return result.available;
  }

  function bindEnrolment() {
    var form = byId("enrolment-form");
    var input = byId("enrol-handle");
    var feedback = byId("handle-feedback");
    input.addEventListener("input", function () { scheduleHandleCheck(input, feedback); });
    form.addEventListener("submit", async function (event) {
      event.preventDefault();
      var output = form.querySelector(".st-submit-state");
      if (!form.reportValidity()) { return; }
      setSubmitState(output, "Checking handle…", "");
      try {
        if (!(await ensureHandleAvailable(input, feedback))) { setSubmitState(output, "Choose an available handle.", "error"); return; }
        var values = formValues(form);
        var payload = {
          handle: values.handle,
          display_name: values.display_name,
          bio: values.bio,
          website: values.website,
          country: values.country,
          org_id: values.org_id || null
        };
        setSubmitState(output, "Opening seller profile…", "");
        var result = await api("/api/studio/seller", jsonOptions("POST", payload));
        state.seller = result.seller;
        state.isSeller = true;
        setSubmitState(output, "Seller profile opened.", "ok");
        await loadOverview();
      } catch (error) {
        if (error.code === "handle_taken") {
          input.dataset.available = "false";
          input.setAttribute("aria-invalid", "true");
          feedback.className = "is-error";
          feedback.textContent = "That handle was just claimed. Choose another.";
        }
        setSubmitState(output, error.message, "error");
      }
    });
  }

  function listingPrice(listing) {
    var parts = [];
    if (int(listing.price_cents)) { parts.push(formatCash(listing.price_cents)); }
    if (int(listing.price_credits)) { parts.push(formatInt(listing.price_credits) + " credits"); }
    return parts.join(" or ") || "Free";
  }

  function listingRow(listing) {
    var actions = '<button class="btn ghost" type="button" data-list-action="edit" data-id="' + esc(listing.id) + '">Edit</button>';
    if (listing.status === "draft" || listing.status === "rejected") {
      actions += '<button class="btn danger" type="button" data-list-action="confirm-delete" data-id="' + esc(listing.id) + '">Delete</button>';
    }
    if (listing.status === "published") {
      actions += '<a class="btn ghost" href="/marketplace#/m/' + encodeURIComponent(listing.slug) + '">View</a>';
      actions += '<button class="btn ghost" type="button" data-list-action="render" data-id="' + esc(listing.id) + '">Regenerate previews</button>';
      actions += '<button class="btn danger" type="button" data-list-action="confirm-unlist" data-id="' + esc(listing.id) + '">Unlist</button>';
    }
    if (listing.status === "unlisted") {
      actions += '<button class="btn primary" type="button" data-list-action="submit" data-id="' + esc(listing.id) + '">Relist</button>';
    }
    return '<article class="st-listing-row" data-listing-id="' + esc(listing.id) + '"><div class="st-listing-main"><h3>' + esc(listing.title) + "</h3>" +
      (listing.summary ? "<p>" + esc(listing.summary) + "</p>" : "") +
      '<div class="st-listing-meta"><span class="st-status is-' + esc(listing.status) + '">' + esc(statusLabel(listing.status)) + "</span>" +
      '<span class="st-status is-' + esc(listing.attestation_status || "none") + '">Attestation: ' + esc(statusLabel(listing.attestation_status || "none")) + "</span>" +
      '<span class="st-pill">' + esc(listingPrice(listing)) + "</span>" +
      (int(listing.stats && listing.stats.sales) ? '<span class="st-pill">' + formatInt(listing.stats.sales) + " sales</span>" : "") +
      (int(listing.stats && listing.stats.downloads) ? '<span class="st-pill">' + formatInt(listing.stats.downloads) + " downloads</span>" : "") +
      "</div></div><div class=\"st-listing-actions\">" + actions + "</div></article>";
  }

  function renderListings(append) {
    var host = byId("listing-list");
    if (!state.listings.length) {
      host.innerHTML = '<div class="mk-empty st-empty"><h2>No listings here</h2><p>' +
        (state.listingStatus ? "There are no " + esc(statusLabel(state.listingStatus)) + " listings. Choose another status or create one." : "Create a listing from your files, or import work from a supported source.") +
        '</p><p><a class="btn primary" href="#new">Create listing</a></p></div>';
    } else {
      var html = state.listings.map(listingRow).join("");
      if (append) { host.insertAdjacentHTML("beforeend", html); } else { host.innerHTML = html; }
    }
    show(byId("listing-more"), !!state.listingCursor);
  }

  async function loadListings(append) {
    if (!state.isSeller) { return; }
    var host = byId("listing-list");
    if (!append) { host.innerHTML = '<div class="mk-skeleton st-skeleton"></div><div class="mk-skeleton st-skeleton"></div>'; }
    var query = [];
    if (state.listingStatus) { query.push("status=" + encodeURIComponent(state.listingStatus)); }
    if (append && state.listingCursor) { query.push("cursor=" + encodeURIComponent(state.listingCursor)); }
    try {
      var result = await api("/api/studio/listings" + (query.length ? "?" + query.join("&") : ""));
      var items = result.items || [];
      state.listings = append ? state.listings.concat(items) : items;
      state.listingCursor = result.next_cursor || null;
      renderListings(false);
    } catch (error) {
      host.innerHTML = '<div class="mk-empty st-empty"><h2>Listings could not load</h2><p>' + esc(error.message) + "</p></div>";
    }
  }

  function showInlineConfirm(row, message, action, id) {
    var old = row.querySelector(".st-confirm");
    if (old) { old.remove(); }
    row.insertAdjacentHTML("beforeend", '<div class="st-confirm"><span>' + esc(message) + '</span><button class="btn ghost" type="button" data-list-action="cancel-confirm">Cancel</button><button class="btn danger" type="button" data-list-action="' + esc(action) + '" data-id="' + esc(id) + '">Confirm</button></div>');
  }

  async function listingAction(button) {
    var action = button.dataset.listAction;
    var id = button.dataset.id;
    var row = button.closest(".st-listing-row");
    if (action === "cancel-confirm") { var confirm = button.closest(".st-confirm"); if (confirm) { confirm.remove(); } return; }
    if (action === "confirm-delete") { showInlineConfirm(row, "Delete this draft and its uploaded assets permanently?", "delete", id); return; }
    if (action === "confirm-unlist") { showInlineConfirm(row, "Unlist this model? Existing buyers keep access, but it leaves the storefront.", "unlist", id); return; }
    button.disabled = true;
    try {
      if (action === "edit") { await editListing(id); return; }
      if (action === "delete") { await api("/api/studio/listings/" + encodeURIComponent(id), { method: "DELETE" }); notice("Draft deleted.", ""); }
      if (action === "unlist") { await api("/api/studio/listings/" + encodeURIComponent(id) + "/unlist", jsonOptions("POST", {})); notice("Listing unlisted.", ""); }
      if (action === "submit") { await api("/api/studio/listings/" + encodeURIComponent(id) + "/submit", jsonOptions("POST", {})); notice("Listing submitted.", ""); }
      if (action === "render") { await api("/api/studio/listings/" + encodeURIComponent(id) + "/render", jsonOptions("POST", {})); notice("Preview generation requested.", ""); }
      await loadListings(false);
      await loadOverview();
    } catch (error) {
      notice(error.message, "error");
      button.disabled = false;
    }
  }

  function composerFromListing(listing) {
    var composer = freshComposer();
    composer.id = listing.id;
    composer.status = listing.status;
    Object.keys(composer.data).forEach(function (key) {
      if (key === "process_note" || key === "tools" || key === "hours" || key === "ai_tools_note") { return; }
      if (Object.prototype.hasOwnProperty.call(listing, key)) { composer.data[key] = listing[key] == null ? "" : listing[key]; }
    });
    composer.data.tags = Array.isArray(listing.tags) ? listing.tags.join(", ") : (listing.tags || "");
    if (listing.attestation) {
      composer.data.process_note = listing.attestation.process_note || "";
      composer.data.tools = Array.isArray(listing.attestation.tools) ? listing.attestation.tools.join(", ") : "";
      composer.data.hours = listing.attestation.hours || "";
      composer.data.ai_tools_note = listing.attestation.ai_tools_note || "";
    }
    composer.assets = listing.assets || [];
    composer.versions = listing.versions || [];
    return composer;
  }

  async function editListing(id) {
    try {
      var result = await api("/api/studio/listings/" + encodeURIComponent(id));
      state.composer = composerFromListing(result.listing);
      window.location.hash = "new";
      renderComposer();
    } catch (error) { notice(error.message, "error"); }
  }

  function metaLimits() {
    return state.meta && state.meta.limits ? state.meta.limits : {};
  }
  function allowedExtensions() {
    var limits = metaLimits();
    return [].concat(limits.source_extensions || [], limits.image_extensions || [], limits.document_extensions || []).map(function (x) { return String(x).toLowerCase(); });
  }
  function fileExtension(name) {
    var lower = String(name || "").toLowerCase();
    if (lower.endsWith(".step+")) { return ".step+"; }
    var dot = lower.lastIndexOf(".");
    return dot >= 0 ? lower.slice(dot) : "";
  }
  function fileKind(file) {
    var ext = fileExtension(file.name);
    var limits = metaLimits();
    if ((limits.image_extensions || []).indexOf(ext) >= 0) { return "image"; }
    if ((limits.document_extensions || []).indexOf(ext) >= 0 && (limits.source_extensions || []).indexOf(ext) < 0) { return "document"; }
    return "source";
  }
  function defaultRole(file) {
    var roles = state.composer.assets.concat(state.composer.files);
    if (fileKind(file) === "image") { return roles.some(function (x) { return x.role === "thumbnail"; }) ? "gallery" : "thumbnail"; }
    return roles.some(function (x) { return x.role === "primary"; }) ? "" : "primary";
  }
  function fileError(file) {
    var max = int(metaLimits().max_asset_bytes);
    var allowed = allowedExtensions();
    var ext = fileExtension(file.name);
    if (!max || !allowed.length) { return "Upload limits are unavailable. Reload before choosing files."; }
    if (allowed.indexOf(ext) < 0) { return "Unsupported file type " + (ext || "without an extension") + "."; }
    if (file.size > max) { return "File is " + formatBytes(file.size) + "; the per-file limit is " + formatBytes(max) + "."; }
    if (!file.size) { return "Empty files cannot be uploaded."; }
    return "";
  }

  function addFiles(fileList) {
    Array.prototype.forEach.call(fileList, function (file) {
      var error = fileError(file);
      var item = { key: Date.now().toString(36) + Math.random().toString(36).slice(2), file: file, role: "", error: error, progress: 0, uploaded: false };
      item.role = error ? "" : defaultRole(file);
      state.composer.files.push(item);
    });
    renderComposer();
  }

  function roleOptions(selected) {
    return [
      ["", "No special role"], ["primary", "Primary file"], ["gallery", "Gallery"],
      ["sample", "Free sample"], ["thumbnail", "Thumbnail"]
    ].map(function (item) { return '<option value="' + item[0] + '"' + (selected === item[0] ? " selected" : "") + ">" + item[1] + "</option>"; }).join("");
  }

  function filesStage() {
    var max = int(metaLimits().max_asset_bytes);
    var pending = state.composer.files.map(function (item) {
      return '<div class="st-file-row" data-file-key="' + esc(item.key) + '"><div class="st-file-name"><strong>' + esc(item.file.name) + "</strong><small>" +
        (item.error ? '<span class="is-error">' + esc(item.error) + "</span>" : formatBytes(item.file.size) + (item.uploaded ? " · uploaded" : " · staged locally")) +
        '</small></div><select data-file-role aria-label="Role for ' + esc(item.file.name) + '"' + (item.error ? " disabled" : "") + ">" + roleOptions(item.role) +
        '</select><button class="st-file-remove" type="button" data-remove-file aria-label="Remove ' + esc(item.file.name) + '">Remove</button>' +
        (item.progress ? '<div class="st-progress" aria-label="Upload progress"><span style="width:' + Math.min(100, item.progress) + '%"></span></div>' : "") + "</div>";
    }).join("");
    var existing = state.composer.assets.map(function (asset) {
      return '<div class="st-file-row" data-asset-id="' + esc(asset.id) + '"><div class="st-file-name"><strong>' + esc(asset.filename) + "</strong><small>Uploaded" + (asset.bytes ? " · " + formatBytes(asset.bytes) : "") +
        '</small></div><select data-asset-role aria-label="Role for ' + esc(asset.filename) + '">' + roleOptions(asset.role || "") +
        '</select><button class="st-file-remove" type="button" data-confirm-asset-delete>Remove</button></div>';
    }).join("");
    return '<div class="st-stage" data-stage="files"><div class="st-stage-head"><h2>Add the model files</h2><p>Files stay on this device until the draft is saved. Upload progress is shown for every file.</p></div>' +
      '<label class="st-dropzone" id="file-drop"><input id="file-input" type="file" multiple><span><strong>Drop files here or choose files</strong><br><small>Each file may be up to ' + (max ? formatBytes(max) : "the server limit") + ". Assign its marketplace role below.</small></span></label>" +
      '<div class="st-file-list" id="composer-files">' + existing + pending + "</div></div>";
  }

  function categoryOptions(selected) {
    var categories = state.meta && state.meta.categories ? state.meta.categories : [];
    return '<option value="">Choose a category</option>' + categories.map(function (category) {
      var prefix = category.parent_id ? "— " : "";
      return '<option value="' + esc(category.id) + '"' + (selected === category.id ? " selected" : "") + ">" + prefix + esc(category.name) + "</option>";
    }).join("");
  }

  function essentialsAStage() {
    var d = state.composer.data;
    return '<div class="st-stage" data-stage="essentials-a"><div class="st-stage-head"><h2>Describe the essentials</h2><p>Three fields give buyers enough context to understand the model at a glance.</p></div><div class="st-form">' +
      '<label class="st-field"><span>Title</span><input name="title" value="' + esc(d.title) + '" required minlength="3" maxlength="140"><small>3–140 characters.</small></label>' +
      '<label class="st-field"><span>Summary</span><textarea name="summary" rows="3" maxlength="280">' + esc(d.summary) + '</textarea><small>A concise card description, up to 280 characters.</small></label>' +
      '<label class="st-field"><span>Category</span><select name="category_id" required>' + categoryOptions(d.category_id) + "</select></label></div></div>";
  }

  function essentialsBStage() {
    var d = state.composer.data;
    return '<div class="st-stage" data-stage="essentials-b"><div class="st-stage-head"><h2>Add useful detail</h2><p>Tags improve discovery. Description supports markdown on the storefront and is always rendered safely.</p></div><div class="st-form">' +
      '<label class="st-field"><span>Tags</span><input name="tags" value="' + esc(d.tags) + '" maxlength="800" placeholder="nema17, bracket, step"><small>Comma-separated; up to 24 tags, each 2–32 characters.</small></label>' +
      '<label class="st-field"><span>Description</span><textarea name="description" rows="12" maxlength="40000">' + esc(d.description) + '</textarea><small>Materials, dimensions, assembly notes, tolerances, and what the files contain.</small></label></div></div>';
  }

  function licensePermissions(license) {
    var permissions = [];
    permissions.push(license.allows_commercial ? "commercial use" : "non-commercial only");
    permissions.push(license.allows_derivatives ? "derivatives allowed" : "no derivatives");
    if (license.requires_attribution) { permissions.push("attribution required"); }
    if (license.share_alike) { permissions.push("share-alike required"); }
    return permissions.join(", ");
  }

  function licenseOptions(selected) {
    var licenses = state.meta && state.meta.licenses ? state.meta.licenses : [];
    var groups = [
      ["Open source", licenses.filter(function (x) { return x.is_open_source; })],
      ["Free", licenses.filter(function (x) { return !x.is_open_source && !x.sellable; })],
      ["Commercial", licenses.filter(function (x) { return x.sellable; })]
    ];
    return '<option value="">Choose a license</option>' + groups.map(function (group) {
      if (!group[1].length) { return ""; }
      return '<optgroup label="' + group[0] + '">' + group[1].map(function (license) {
        return '<option value="' + esc(license.id) + '"' + (selected === license.id ? " selected" : "") + ">" + esc(license.name + " — " + licensePermissions(license)) + "</option>";
      }).join("") + "</optgroup>";
    }).join("");
  }

  function selectedLicense() {
    var licenses = state.meta && state.meta.licenses ? state.meta.licenses : [];
    return licenses.find(function (license) { return license.id === state.composer.data.license_id; }) || null;
  }

  function priceStage() {
    var d = state.composer.data;
    var license = selectedLicense();
    var sellable = !license || license.sellable;
    var kind = sellable ? d.pricing_kind : "free";
    if (!sellable) { d.pricing_kind = "free"; d.price_cents = 0; d.price_credits = 0; }
    var cash = kind === "cash" || kind === "cash_or_credits";
    var credits = kind === "credits" || kind === "cash_or_credits";
    var permissions = license ? '<div class="st-permissions">' + licensePermissions(license).split(", ").map(function (x) { return '<span class="st-pill">' + esc(x) + "</span>"; }).join("") + "</div>" : "";
    return '<div class="st-stage" data-stage="price"><div class="st-stage-head"><h2>Set licensing and price</h2><p>The license controls whether charging is allowed. Fee and take-home update before you publish.</p></div><div class="st-form">' +
      '<label class="st-field"><span>License</span><select name="license_id" required>' + licenseOptions(d.license_id) + "</select><small>Every option states its actual permissions.</small>" + permissions + "</label>" +
      (!sellable ? '<div class="st-rule-box is-warn"><strong>This license cannot be sold.</strong><br>Price fields are disabled because its permissions require a free download. Choose a commercial license to charge.</div>' : "") +
      '<fieldset class="st-field"' + (!sellable ? " disabled" : "") + '><span>Pricing</span><div class="st-choice-grid">' +
      [["free", "Free", "No order or platform fee."], ["cash", "Cash", "Paid in USD through Stripe Connect."], ["credits", "Credits", "Paid in AI tokens, spendable immediately."], ["cash_or_credits", "Both", "Buyer chooses cash or credits."]].map(function (item) {
        return '<label class="st-choice"><input type="radio" name="pricing_kind" value="' + item[0] + '"' + (kind === item[0] ? " checked" : "") + '><span class="st-choice-body"><strong>' + item[1] + "</strong><small>" + item[2] + "</small></span></label>";
      }).join("") + "</div></fieldset>" +
      '<div class="st-form-grid" id="price-fields">' +
      (cash ? '<label class="st-field"><span>Cash price</span><input name="price_cash" type="number" min="1" max="5000" step="0.01" value="' + (int(d.price_cents) ? (int(d.price_cents) / 100).toFixed(2) : "") + '" required><small>USD, minimum $1.00.</small></label>' : "") +
      (credits ? '<label class="st-field"><span>Credit price</span><input name="price_credits" type="number" min="100" max="5000000" step="1" value="' + (int(d.price_credits) || "") + '" required><small>1 credit equals $0.001 of upstream AI model cost.</small></label>' : "") +
      "</div><div class=\"st-fee-grid\" id=\"fee-preview\"></div>" +
      (kind === "free" ? '<label class="st-choice"><input type="checkbox" name="tips_enabled"' + (d.tips_enabled ? " checked" : "") + '><span class="st-choice-body"><strong>Allow tips</strong><small>Keep the download free while letting people support the work.</small></span></label>' : "") +
      "</div></div>";
  }

  function originStage() {
    var d = state.composer.data;
    return '<div class="st-stage" data-stage="origin"><div class="st-stage-head"><h2>Disclose how the model was made</h2><p>This is a provenance statement, not a marketing tag. Choose the description that is true.</p></div><div class="st-choice-grid">' +
      ["human", "ai_assisted", "ai_generated"].map(function (origin) {
        return '<label class="st-choice"><input type="radio" name="origin" value="' + origin + '"' + (d.origin === origin ? " checked" : "") + '><span class="st-choice-body"><strong>' + ORIGIN_LABELS[origin] + "</strong><small>" + ORIGIN_BLURBS[origin] + "</small></span></label>";
      }).join("") + '</div><label class="st-field"><span>Additional disclosure <em>optional</em></span><textarea name="origin_note" rows="3" maxlength="2000">' + esc(d.origin_note) + "</textarea><small>Add context buyers should know about the process.</small></label>" +
      (d.origin === "human" ? '<div class="st-rule-box"><strong>Publishing is allowed immediately.</strong><br>Your Human-made disclosure appears on the listing, but the curated Human-made shelf requires a reviewer to verify the attestation in the next steps.</div>' : "") + "</div>";
  }

  function attestationAStage() {
    var d = state.composer.data;
    var count = String(d.process_note || "").trim().length;
    return '<div class="st-stage" data-stage="attestation-a"><div class="st-stage-head"><h2>Give a reviewer something to judge</h2><p>A checkbox cannot establish provenance. Explain the decisions and physical or CAD process that produced the geometry.</p></div><div class="st-form">' +
      '<label class="st-field"><span>Process notes</span><textarea name="process_note" rows="10" minlength="120" maxlength="8000" required>' + esc(d.process_note) + '</textarea><small>A reviewer needs concrete process detail, not a claim: sketches, measurements, iterations, constraints, fabrication, and verification.</small><span class="st-counter ' + (count >= 120 ? "is-ok" : "is-short") + '" id="process-counter">' + count + " / 120 minimum</span></label>" +
      '<label class="st-field"><span>Tools used</span><input name="tools" value="' + esc(d.tools) + '" placeholder="Calipers, SolidWorks 2025, Ender 3"><small>Comma-separated CAD packages, machines, and measuring tools.</small></label></div></div>';
  }

  function attestationBStage() {
    var d = state.composer.data;
    return '<div class="st-stage" data-stage="attestation-b"><div class="st-stage-head"><h2>Complete the attestation</h2><p>AI use does not automatically disqualify a Human-made claim. Honest disclosure gives the reviewer the context to assess the balance.</p></div><div class="st-form">' +
      '<label class="st-field"><span>Approximate hours <em>optional</em></span><input name="hours" type="number" min="0.01" max="99999.99" step="0.25" value="' + esc(d.hours) + '"><small>Include design, testing, and revision time.</small></label>' +
      '<label class="st-field"><span>AI tools used <em>optional and honest</em></span><textarea name="ai_tools_note" rows="5" maxlength="4000">' + esc(d.ai_tools_note) + '</textarea><small>State any AI help plainly. This does not by itself disqualify the listing; hiding material AI involvement undermines the attestation.</small></label></div>' +
      '<div class="st-rule-box"><strong>Curated shelf review</strong><br>You may publish before review. The listing reaches the Human-made shelf only after its attestation status becomes verified.</div></div>';
  }

  function reviewStage() {
    var d = state.composer.data;
    var license = selectedLicense();
    var fileCount = state.composer.assets.length + state.composer.files.filter(function (x) { return !x.error; }).length;
    var html = '<div class="st-stage" data-stage="review"><div class="st-stage-head"><h2>Review and publish</h2><p>Save a private draft, or submit it to the marketplace. Staged files upload with real per-file progress after the draft exists.</p></div><div class="st-review">' +
      '<section class="st-review-section"><h3>' + esc(d.title) + "</h3>" + (d.summary ? "<p>" + esc(d.summary) + "</p>" : "") + '<p>' + esc(fileCount) + " file" + (fileCount === 1 ? "" : "s") + " · " + esc((state.meta.categories || []).find(function (x) { return x.id === d.category_id; })?.name || "No category") + "</p></section>" +
      '<section class="st-review-section"><h3>License and price</h3><p>' + esc(license ? license.name : "No license") + "</p><p>" + esc(listingPrice(d)) + "</p><div id=\"review-fees\" class=\"st-fee-grid\"></div></section>" +
      '<section class="st-review-section"><h3>Provenance</h3><p><strong>' + esc(ORIGIN_LABELS[d.origin] || "Not selected") + "</strong> — " + esc(ORIGIN_BLURBS[d.origin] || "") + "</p>" +
      (d.origin === "human" ? '<p>Your attestation submits as pending. Publishing is immediate when otherwise eligible; curated Human-made placement waits for review.</p>' : "") + "</section>" +
      '<div class="st-review-actions"><button class="btn ghost" type="button" data-composer-save="draft">Save draft</button><button class="btn primary" type="button" data-composer-save="publish">Submit listing</button></div>';
    if (state.composer.status === "published") {
      html += '<section class="st-review-section"><h3>Create a new version</h3><p>Versions are available only after publication, so buyers can understand meaningful updates.</p><div class="st-form-grid"><label class="st-field"><span>Version label</span><input name="version_label" maxlength="40" placeholder="1.1"></label><label class="st-field"><span>Changelog</span><textarea name="version_changelog" maxlength="8000" rows="3"></textarea></label></div><button class="btn ghost" type="button" data-create-version>Create version</button></section>';
    }
    return html + "</div></div>";
  }

  function stageHtml(stage) {
    if (stage === "files") { return filesStage(); }
    if (stage === "essentials-a") { return essentialsAStage(); }
    if (stage === "essentials-b") { return essentialsBStage(); }
    if (stage === "price") { return priceStage(); }
    if (stage === "origin") { return originStage(); }
    if (stage === "attestation-a") { return attestationAStage(); }
    if (stage === "attestation-b") { return attestationBStage(); }
    return reviewStage();
  }

  function updateStepBar(stage) {
    var group = STAGE_GROUPS[stage];
    var order = ["files", "essentials", "price", "origin", "review"];
    var current = order.indexOf(group);
    document.querySelectorAll("#composer-steps li").forEach(function (li) {
      var index = order.indexOf(li.dataset.stepGroup);
      li.classList.toggle("is-current", index === current);
      li.classList.toggle("is-complete", index < current);
    });
  }

  function renderComposer() {
    if (!state.composer) { state.composer = freshComposer(); }
    var stages = activeStages();
    state.composer.step = Math.max(0, Math.min(state.composer.step, stages.length - 1));
    var stage = currentStage();
    byId("composer-title").textContent = state.composer.id ? "Edit listing" : "Create a listing";
    show(byId("composer-reset"), !!state.composer.id || state.composer.files.length > 0 || !!state.composer.data.title);
    byId("composer-stage").innerHTML = stageHtml(stage);
    updateStepBar(stage);
    show(byId("composer-back"), state.composer.step > 0);
    show(byId("composer-next"), stage !== "review");
    byId("composer-next").textContent = "Continue";
    setSubmitState(byId("composer-state"), "", "");
    bindStage(stage);
    if (stage === "price" || stage === "review") { updateFees(stage === "review" ? byId("review-fees") : byId("fee-preview")); }
  }

  function bindStage(stage) {
    var host = byId("composer-stage");
    if (stage === "files") {
      var drop = byId("file-drop");
      var input = byId("file-input");
      drop.addEventListener("click", function () { input.click(); });
      input.addEventListener("change", function () { addFiles(input.files); });
      ["dragenter", "dragover"].forEach(function (name) { drop.addEventListener(name, function (event) { event.preventDefault(); drop.classList.add("is-over"); }); });
      ["dragleave", "drop"].forEach(function (name) { drop.addEventListener(name, function (event) { event.preventDefault(); drop.classList.remove("is-over"); }); });
      drop.addEventListener("drop", function (event) { addFiles(event.dataTransfer.files); });
      host.querySelectorAll("[data-file-role]").forEach(function (select) { select.addEventListener("change", function () { var item = state.composer.files.find(function (x) { return x.key === select.closest("[data-file-key]").dataset.fileKey; }); if (item) { item.role = select.value; } }); });
      host.querySelectorAll("[data-remove-file]").forEach(function (button) { button.addEventListener("click", function () { var key = button.closest("[data-file-key]").dataset.fileKey; state.composer.files = state.composer.files.filter(function (x) { return x.key !== key; }); renderComposer(); }); });
      host.querySelectorAll("[data-asset-role]").forEach(function (select) { select.addEventListener("change", function () { patchAssetRole(select); }); });
      host.querySelectorAll("[data-confirm-asset-delete]").forEach(function (button) { button.addEventListener("click", function () { confirmAssetDelete(button); }); });
    }
    if (stage === "price") {
      host.querySelector("[name=license_id]").addEventListener("change", function (event) { collectStage(); state.composer.data.license_id = event.target.value; renderComposer(); });
      host.querySelectorAll("[name=pricing_kind]").forEach(function (radio) { radio.addEventListener("change", function () { collectStage(); state.composer.data.pricing_kind = radio.value; if (radio.value === "cash_or_credits" && !state.composer.creditOverridden) { state.composer.data.price_credits = suggestedCredits(state.composer.data.price_cents); } renderComposer(); }); });
      var cash = host.querySelector("[name=price_cash]");
      var credits = host.querySelector("[name=price_credits]");
      if (cash) { cash.addEventListener("input", function () { state.composer.data.price_cents = Math.round(Number(cash.value || 0) * 100); if (state.composer.data.pricing_kind === "cash_or_credits" && !state.composer.creditOverridden && credits) { state.composer.data.price_credits = suggestedCredits(state.composer.data.price_cents); credits.value = state.composer.data.price_credits || ""; } updateFees(byId("fee-preview")); }); }
      if (credits) { credits.addEventListener("input", function () { state.composer.creditOverridden = true; state.composer.data.price_credits = int(credits.value); updateFees(byId("fee-preview")); }); }
    }
    if (stage === "origin") {
      host.querySelectorAll("[name=origin]").forEach(function (radio) { radio.addEventListener("change", function () { collectStage(); state.composer.data.origin = radio.value; renderComposer(); }); });
    }
    if (stage === "attestation-a") {
      var note = host.querySelector("[name=process_note]");
      note.addEventListener("input", function () { var count = note.value.trim().length; var counter = byId("process-counter"); counter.textContent = count + " / 120 minimum"; counter.className = "st-counter " + (count >= 120 ? "is-ok" : "is-short"); });
    }
    if (stage === "review") {
      host.querySelectorAll("[data-composer-save]").forEach(function (button) { button.addEventListener("click", function () { saveComposer(button.dataset.composerSave === "publish"); }); });
      var version = host.querySelector("[data-create-version]");
      if (version) { version.addEventListener("click", function () { createVersion(version); }); }
    }
  }

  function collectStage() {
    var stage = currentStage();
    var host = byId("composer-stage");
    if (!host) { return; }
    var d = state.composer.data;
    function value(name) { var el = host.querySelector("[name='" + name + "']"); return el ? el.value.trim() : null; }
    if (stage === "essentials-a") { d.title = value("title") || ""; d.summary = value("summary") || ""; d.category_id = value("category_id") || ""; }
    if (stage === "essentials-b") { d.tags = value("tags") || ""; d.description = value("description") || ""; }
    if (stage === "price") {
      d.license_id = value("license_id") || "";
      var kind = host.querySelector("[name=pricing_kind]:checked");
      d.pricing_kind = kind ? kind.value : "free";
      d.price_cents = host.querySelector("[name=price_cash]") ? Math.round(Number(value("price_cash") || 0) * 100) : 0;
      d.price_credits = host.querySelector("[name=price_credits]") ? int(value("price_credits")) : 0;
      var tips = host.querySelector("[name=tips_enabled]"); d.tips_enabled = !!(tips && tips.checked);
    }
    if (stage === "origin") { var origin = host.querySelector("[name=origin]:checked"); d.origin = origin ? origin.value : ""; d.origin_note = value("origin_note") || ""; }
    if (stage === "attestation-a") { d.process_note = value("process_note") || ""; d.tools = value("tools") || ""; }
    if (stage === "attestation-b") { d.hours = value("hours") || ""; d.ai_tools_note = value("ai_tools_note") || ""; }
  }

  function validateStage() {
    collectStage();
    var stage = currentStage();
    var d = state.composer.data;
    if (stage === "files") {
      if (state.composer.files.some(function (x) { return !!x.error; })) { return "Remove files with validation errors before continuing."; }
      if (!state.composer.files.length && !state.composer.assets.length) { return "Add at least one model or image file."; }
    }
    if (stage === "essentials-a") {
      if (d.title.trim().length < 3) { return "Title must be at least 3 characters."; }
      if (d.summary.length > 280) { return "Summary must be 280 characters or fewer."; }
      if (!d.category_id) { return "Choose a category."; }
    }
    if (stage === "essentials-b" && d.description.length > 40000) { return "Description must be 40,000 characters or fewer."; }
    if (stage === "price") {
      var license = selectedLicense();
      if (!license) { return "Choose a license."; }
      if (!license.sellable && d.pricing_kind !== "free") { return "This license requires a free listing."; }
      if ((d.pricing_kind === "cash" || d.pricing_kind === "cash_or_credits") && (d.price_cents < 100 || d.price_cents > 500000)) { return "Cash price must be between $1.00 and $5,000.00."; }
      if ((d.pricing_kind === "credits" || d.pricing_kind === "cash_or_credits") && (d.price_credits < 100 || d.price_credits > 5000000)) { return "Credit price must be between 100 and 5,000,000 credits."; }
    }
    if (stage === "origin" && !ORIGIN_BLURBS[d.origin]) { return "Choose the truthful provenance disclosure."; }
    if (stage === "attestation-a") {
      var length = d.process_note.trim().length;
      if (length < 120 || length > 8000) { return "Process notes must be between 120 and 8,000 characters."; }
    }
    if (stage === "attestation-b" && d.hours && Number(d.hours) <= 0) { return "Hours must be greater than zero when provided."; }
    return "";
  }

  function suggestedCredits(cents) {
    var rate = int(state.meta && state.meta.fee && state.meta.fee.credits_per_dollar);
    return rate > 0 ? Math.floor(int(cents) * rate / 100) : 0;
  }

  function updateFees(host) {
    if (!host || !state.meta) { return; }
    var fee = state.meta.fee || {};
    var d = state.composer.data;
    var html = "";
    if (d.pricing_kind === "cash" || d.pricing_kind === "cash_or_credits") {
      var cashFee = Math.floor(int(d.price_cents) * int(fee.cash_bps) / 10000);
      html += '<div class="st-fee-card"><span>Cash platform fee (' + (int(fee.cash_bps) / 100).toFixed(2).replace(/\.00$/, "") + '%)</span><strong>' + formatCash(cashFee) + '</strong><span>You take home ' + formatCash(int(d.price_cents) - cashFee) + ".</span></div>";
    }
    if (d.pricing_kind === "credits" || d.pricing_kind === "cash_or_credits") {
      var creditFee = Math.floor(int(d.price_credits) * int(fee.credit_bps) / 10000);
      html += '<div class="st-fee-card"><span>Credit platform fee (' + (int(fee.credit_bps) / 100).toFixed(2).replace(/\.00$/, "") + '%)</span><strong>' + formatInt(creditFee) + ' credits</strong><span>You take home ' + formatInt(int(d.price_credits) - creditFee) + " credits.</span></div>";
    }
    if (!html) { html = '<div class="st-rule-box">Free listings have no platform fee.</div>'; }
    host.innerHTML = html;
  }

  async function patchAssetRole(select) {
    var row = select.closest("[data-asset-id]");
    select.disabled = true;
    try {
      var result = await api("/api/studio/listings/" + encodeURIComponent(state.composer.id) + "/assets/" + encodeURIComponent(row.dataset.assetId), jsonOptions("PATCH", { role: select.value }));
      var index = state.composer.assets.findIndex(function (x) { return x.id === result.asset.id; });
      if (index >= 0) { state.composer.assets[index] = result.asset; }
      setSubmitState(byId("composer-state"), "Asset role saved.", "ok");
    } catch (error) { setSubmitState(byId("composer-state"), error.message, "error"); select.disabled = false; }
  }

  function confirmAssetDelete(button) {
    var row = button.closest("[data-asset-id]");
    if (row.querySelector(".st-confirm")) { return; }
    row.insertAdjacentHTML("beforeend", '<div class="st-confirm"><span>Remove this uploaded asset permanently?</span><button class="btn ghost" type="button" data-cancel-asset>Cancel</button><button class="btn danger" type="button" data-delete-asset>Remove asset</button></div>');
    row.querySelector("[data-cancel-asset]").addEventListener("click", function () { row.querySelector(".st-confirm").remove(); });
    row.querySelector("[data-delete-asset]").addEventListener("click", async function (event) {
      event.target.disabled = true;
      try {
        await api("/api/studio/listings/" + encodeURIComponent(state.composer.id) + "/assets/" + encodeURIComponent(row.dataset.assetId), { method: "DELETE" });
        state.composer.assets = state.composer.assets.filter(function (x) { return x.id !== row.dataset.assetId; });
        renderComposer();
      } catch (error) { setSubmitState(byId("composer-state"), error.message, "error"); event.target.disabled = false; }
    });
  }

  function listingPayload() {
    var d = state.composer.data;
    return {
      title: d.title,
      summary: d.summary,
      description: d.description,
      category_id: d.category_id,
      license_id: d.license_id,
      pricing_kind: d.pricing_kind,
      price_cents: int(d.price_cents),
      price_credits: int(d.price_credits),
      tips_enabled: !!d.tips_enabled,
      origin: d.origin,
      origin_note: d.origin_note,
      tags: d.tags
    };
  }

  function uploadAsset(item) {
    return new Promise(function (resolve, reject) {
      var xhr = new XMLHttpRequest();
      var form = new FormData();
      form.append("file", item.file, item.file.name);
      form.append("kind", fileKind(item.file));
      form.append("role", item.role || "");
      form.append("gated", item.role === "sample" || item.role === "gallery" || item.role === "thumbnail" ? "false" : "true");
      xhr.open("POST", "/api/studio/listings/" + encodeURIComponent(state.composer.id) + "/assets");
      xhr.upload.addEventListener("progress", function (event) {
        if (!event.lengthComputable) { return; }
        item.progress = Math.round(event.loaded * 100 / event.total);
        var bar = document.querySelector('[data-file-key="' + CSS.escape(item.key) + '"] .st-progress span');
        if (bar) { bar.style.width = item.progress + "%"; }
      });
      xhr.addEventListener("load", function () {
        var data = null;
        try { data = JSON.parse(xhr.responseText); } catch (e) { /* non-JSON */ }
        if (xhr.status < 200 || xhr.status >= 300) {
          var detail = data && data.detail;
          var message = detail && typeof detail === "object" ? detail.detail : detail;
          var error = new Error(message || xhr.status + " " + xhr.statusText);
          error.code = detail && typeof detail === "object" ? detail.code : "upload_failed";
          reject(error);
          return;
        }
        item.progress = 100;
        item.uploaded = true;
        resolve(data.asset);
      });
      xhr.addEventListener("error", function () { reject(new Error("Upload connection failed for " + item.file.name + ".")); });
      xhr.addEventListener("abort", function () { reject(new Error("Upload canceled for " + item.file.name + ".")); });
      xhr.send(form);
    });
  }

  async function uploadPending() {
    var pending = state.composer.files.filter(function (item) { return !item.error && !item.uploaded; });
    for (var i = 0; i < pending.length; i += 1) {
      setSubmitState(byId("composer-state"), "Uploading " + pending[i].file.name + " (" + (i + 1) + " of " + pending.length + ")…", "");
      var asset = await uploadAsset(pending[i]);
      state.composer.assets.push(asset);
    }
    state.composer.files = state.composer.files.filter(function (item) { return !item.uploaded; });
  }

  async function saveComposer(publish) {
    if (state.composer.busy) { return; }
    state.composer.busy = true;
    byId("composer-stage").querySelectorAll("button").forEach(function (button) { button.disabled = true; });
    try {
      setSubmitState(byId("composer-state"), state.composer.id ? "Saving changes…" : "Creating draft…", "");
      var result;
      if (state.composer.id) {
        result = await api("/api/studio/listings/" + encodeURIComponent(state.composer.id), jsonOptions("PATCH", listingPayload()));
      } else {
        result = await api("/api/studio/listings", jsonOptions("POST", listingPayload()));
        state.composer.id = result.listing.id;
      }
      state.composer.status = result.listing.status;
      await uploadPending();
      if (state.composer.data.origin === "human") {
        setSubmitState(byId("composer-state"), "Submitting provenance attestation…", "");
        var d = state.composer.data;
        await api("/api/studio/listings/" + encodeURIComponent(state.composer.id) + "/attestation", jsonOptions("POST", {
          process_note: d.process_note,
          tools: d.tools.split(",").map(function (tool) { return tool.trim(); }).filter(Boolean),
          hours: d.hours ? Number(d.hours) : null,
          ai_tools_note: d.ai_tools_note
        }));
      }
      if (publish) {
        setSubmitState(byId("composer-state"), "Submitting listing…", "");
        result = await api("/api/studio/listings/" + encodeURIComponent(state.composer.id) + "/submit", jsonOptions("POST", {}));
        notice(result.listing.status === "in_review" ? "Listing submitted for review." : "Listing published.", "");
      } else {
        notice("Draft saved.", "");
      }
      state.composer = null;
      await loadOverview();
      window.location.hash = "listings";
    } catch (error) {
      setSubmitState(byId("composer-state"), error.message, "error");
      state.composer.busy = false;
      byId("composer-stage").querySelectorAll("button").forEach(function (button) { button.disabled = false; });
    }
  }

  async function createVersion(button) {
    var host = byId("composer-stage");
    var label = host.querySelector("[name=version_label]").value.trim();
    var changelog = host.querySelector("[name=version_changelog]").value.trim();
    if (!label) { setSubmitState(byId("composer-state"), "Enter a version label.", "error"); return; }
    button.disabled = true;
    try {
      var result = await api("/api/studio/listings/" + encodeURIComponent(state.composer.id) + "/versions", jsonOptions("POST", { label: label, changelog: changelog }));
      state.composer.versions.push(result.version);
      setSubmitState(byId("composer-state"), "Version " + result.version.label + " created.", "ok");
      host.querySelector("[name=version_label]").value = "";
      host.querySelector("[name=version_changelog]").value = "";
    } catch (error) { setSubmitState(byId("composer-state"), error.message, "error"); }
    button.disabled = false;
  }

  function bindComposerShell() {
    byId("composer-back").addEventListener("click", function () {
      collectStage();
      state.composer.step = Math.max(0, state.composer.step - 1);
      renderComposer();
    });
    byId("composer-next").addEventListener("click", function () {
      var error = validateStage();
      if (error) { setSubmitState(byId("composer-state"), error, "error"); return; }
      state.composer.step = Math.min(activeStages().length - 1, state.composer.step + 1);
      renderComposer();
    });
    byId("composer-reset").addEventListener("click", function () {
      var button = byId("composer-reset");
      if (button.dataset.confirm !== "true") {
        button.dataset.confirm = "true";
        button.textContent = "Discard unsaved changes?";
        button.classList.add("danger");
        return;
      }
      state.composer = freshComposer();
      button.dataset.confirm = "";
      button.textContent = "Start over";
      button.classList.remove("danger");
      renderComposer();
    });
  }

  async function loadSources() {
    if (state.sources.length) { renderSourcePicker(); return; }
    try {
      var result = await api("/api/studio/sources");
      state.sources = result.sources || result.items || [];
      renderSourcePicker();
    } catch (error) {
      byId("import-source").innerHTML = '<option value="">Sources unavailable</option>';
      setSubmitState(byId("import-state"), error.message, "error");
    }
  }

  function renderSourcePicker() {
    var select = byId("import-source");
    if (!state.sources.length) {
      select.innerHTML = '<option value="">No import sources available</option>';
      byId("source-capability").textContent = "No source integration is currently enabled.";
      return;
    }
    select.innerHTML = state.sources.map(function (source) { return '<option value="' + esc(source.id) + '">' + esc(source.name) + "</option>"; }).join("");
    updateSourceCapability();
  }

  function currentSource() {
    var id = byId("import-source").value;
    return state.sources.find(function (source) { return source.id === id; }) || null;
  }

  function updateSourceCapability() {
    var source = currentSource();
    var box = byId("source-capability");
    if (!source) { box.textContent = "Choose an enabled source."; return; }
    if (source.file_fetch_available) {
      box.className = "st-capability";
      box.innerHTML = '<strong>Files may be fetched.</strong><br>This source provides an authorized API or your connected account can export your own file.';
    } else {
      box.className = "st-capability is-warn";
      box.innerHTML = source.supports_file_fetch
        ? '<strong>Metadata only right now.</strong><br>This integration cannot fetch files in its current configuration. Attach the model file after import.'
        : '<strong>Metadata only.</strong><br>We can prefill public title, description, author, license, and images. You must attach the model file yourself because this source does not grant automated file retrieval. That boundary protects its licensing terms.';
    }
  }

  function importPayload(result) {
    var record = result.import || result;
    return { record: record, preview: record.preview || record.payload || result.preview || result.payload || {} };
  }

  async function fetchImport(id) {
    var result = await api("/api/studio/imports/" + encodeURIComponent(id));
    state.activeImport = importPayload(result);
    renderImportPreview();
  }

  function importImages(preview) {
    var images = preview.images || preview.image_urls || [];
    return images.map(function (item) { return typeof item === "string" ? item : (item.url || ""); }).filter(safeHttpUrl);
  }

  function renderImportPreview() {
    var host = byId("import-preview");
    if (!state.activeImport) { return; }
    var record = state.activeImport.record;
    var preview = state.activeImport.preview;
    if (record.status === "pending") {
      host.innerHTML = '<div class="st-skeleton-stack"><div class="mk-skeleton st-skeleton"></div><p class="muted">The source page is still being read.</p><button class="btn ghost" type="button" id="refresh-import">Refresh preview</button></div>';
      byId("refresh-import").addEventListener("click", function () { fetchImport(record.id); });
      return;
    }
    if (record.status === "failed") {
      host.innerHTML = '<div class="mk-empty st-empty"><h2>Import could not be read</h2><p>' + esc(record.error || "The source did not return usable public metadata.") + "</p></div>";
      return;
    }
    var detectedLicense = preview.license_hint || "";
    var author = preview.author || preview.source_author || "";
    var images = importImages(preview);
    var source = state.sources.find(function (item) { return item.id === record.source_id; }) || currentSource();
    var sourceFetch = !!(source && source.file_fetch_available);
    host.innerHTML = '<div class="st-panel-heading"><div><p class="st-eyebrow">Review what was read</p><h2>Accept or override each field</h2></div><span class="st-status is-' + esc(record.status) + '">' + esc(statusLabel(record.status)) + "</span></div>" +
      '<form id="import-accept" class="st-form" novalidate>' +
      '<label class="st-field"><span>Title</span><input name="title" required minlength="3" maxlength="140" value="' + esc(preview.title || "") + '"><small>Detected: ' + esc(preview.title || "none") + "</small></label>" +
      '<label class="st-field"><span>Summary</span><textarea name="summary" maxlength="280" rows="3">' + esc(preview.summary || "") + '</textarea><small>Detected text remains visible until you override it.</small></label>' +
      '<label class="st-field"><span>Description</span><textarea name="description" maxlength="40000" rows="6">' + esc(preview.description || "") + "</textarea></label>" +
      '<label class="st-field"><span>Source author</span><input name="source_author" maxlength="300" value="' + esc(author) + '"><small>Detected attribution: ' + esc(author || "none") + ". Correct it if needed; do not erase required attribution.</small></label>" +
      '<label class="st-field"><span>Detected license</span><select name="license_id" required>' + licenseOptions(detectedLicense) + "</select><small>Detected: " + esc(detectedLicense || "none") + "</small></label>" +
      (detectedLicense ? '<div class="st-conflict" id="license-decision"><strong>License decision required</strong><p>The source reported ' + esc(detectedLicense) + '. Accept that license to continue. Choosing a conflicting license is refused rather than silently overwriting the source.</p><label><input type="checkbox" name="confirm_detected_license"> I confirm the detected license is the one this draft should use.</label></div>' : '<div class="st-rule-box">No license was detected. Choose the license you are entitled to apply before accepting.</div>') +
      '<label class="st-field"><span>Category</span><select name="category_id" required>' + categoryOptions("") + "</select></label>" +
      '<label class="st-field"><span>Tags</span><input name="tags" value="' + esc(Array.isArray(preview.tags) ? preview.tags.join(", ") : (preview.tags || "")) + '"></label>' +
      '<fieldset class="st-field"><span>Provenance</span><div class="st-choice-grid">' + ["human", "ai_assisted", "ai_generated"].map(function (origin) { return '<label class="st-choice"><input type="radio" name="origin" value="' + origin + '" required><span class="st-choice-body"><strong>' + ORIGIN_LABELS[origin] + "</strong><small>" + ORIGIN_BLURBS[origin] + "</small></span></label>"; }).join("") + "</div></fieldset>" +
      (images.length ? '<fieldset class="st-field"><span>Images read from the source</span><div class="st-preview-images">' + images.map(function (url, index) { return '<div class="st-preview-image"><img src="' + esc(safeHttpUrl(url)) + '" alt="Source preview ' + (index + 1) + '" loading="lazy"><label><input type="checkbox" name="image_url" value="' + esc(url) + '" checked> Import</label></div>'; }).join("") + "</div><small>Uncheck any image you do not want copied into the draft.</small></fieldset>" : '<div class="st-rule-box">No public images were read. Add a thumbnail in the listing composer.</div>') +
      (sourceFetch ? '<label class="st-choice"><input type="checkbox" name="attach_file" checked><span class="st-choice-body"><strong>Attach the source file</strong><small>This source permits authorized file retrieval.</small></span></label>' : '<div class="st-capability is-warn"><strong>Attach the file yourself after import.</strong><br>This source permits metadata prefill but not automated file retrieval.</div>') +
      '<button class="btn primary" type="submit">Accept into a draft</button><span class="st-submit-state" id="import-accept-state" aria-live="polite"></span></form>';
    var form = byId("import-accept");
    var licenseSelect = form.querySelector("[name=license_id]");
    var decision = form.querySelector("[name=confirm_detected_license]");
    if (detectedLicense) {
      licenseSelect.addEventListener("change", function () {
        var conflict = licenseSelect.value !== detectedLicense;
        byId("license-decision").classList.toggle("is-error", conflict);
        if (conflict) { decision.checked = false; }
      });
    }
    form.addEventListener("submit", function (event) { acceptImport(event, record, detectedLicense, sourceFetch); });
  }

  async function acceptImport(event, record, detectedLicense, sourceFetch) {
    event.preventDefault();
    var form = event.currentTarget;
    var output = byId("import-accept-state");
    if (!form.reportValidity()) { return; }
    var values = formValues(form);
    if (detectedLicense && (values.license_id !== detectedLicense || !form.querySelector("[name=confirm_detected_license]").checked)) {
      setSubmitState(output, "Resolve the detected-license decision before accepting.", "error");
      return;
    }
    var selected = (state.meta.licenses || []).find(function (license) { return license.id === values.license_id; });
    if (selected && selected.requires_attribution && !values.source_author) {
      setSubmitState(output, "This license requires source attribution. Keep or correct the detected author.", "error");
      return;
    }
    var imageUrls = Array.prototype.map.call(form.querySelectorAll("[name=image_url]:checked"), function (input) { return input.value; });
    var payload = {
      origin: values.origin,
      title: values.title,
      summary: values.summary,
      description: values.description,
      category_id: values.category_id,
      license_id: values.license_id,
      tags: values.tags,
      source_author: values.source_author,
      image_urls: imageUrls,
      attach_file: sourceFetch ? !!form.querySelector("[name=attach_file]").checked : false
    };
    form.querySelector("button[type=submit]").disabled = true;
    setSubmitState(output, "Creating imported draft…", "");
    try {
      var result = await api("/api/studio/imports/" + encodeURIComponent(record.id) + "/accept", jsonOptions("POST", payload));
      var listing = result.listing;
      if (!listing && result.listing_id) { listing = (await api("/api/studio/listings/" + encodeURIComponent(result.listing_id))).listing; }
      if (!listing) { throw new Error("The import completed without a listing response."); }
      state.composer = composerFromListing(listing);
      notice(sourceFetch ? "Import accepted. Review the fetched files before publishing." : "Import accepted. Attach the model file before publishing.", "");
      window.location.hash = "new";
      renderComposer();
    } catch (error) {
      setSubmitState(output, error.code === "license_conflict" ? "The detected license conflicts with that choice. Return to the source and verify its license before continuing." : error.message, "error");
      form.querySelector("button[type=submit]").disabled = false;
    }
  }

  function bindImports() {
    byId("import-source").addEventListener("change", updateSourceCapability);
    byId("import-form").addEventListener("submit", async function (event) {
      event.preventDefault();
      var form = event.currentTarget;
      var output = byId("import-state");
      if (!form.reportValidity()) { return; }
      var values = formValues(form);
      setSubmitState(output, "Reading public source data…", "");
      form.querySelector("button[type=submit]").disabled = true;
      try {
        var result = await api("/api/studio/imports", jsonOptions("POST", { source_id: values.source_id, url: values.url }));
        var record = result.import || result;
        if (!record.id) { throw new Error("The import request returned no identifier."); }
        await fetchImport(record.id);
        setSubmitState(output, "Preview ready for review.", "ok");
      } catch (error) { setSubmitState(output, error.message, "error"); }
      form.querySelector("button[type=submit]").disabled = false;
    });
  }

  function sparkline(series) {
    var values = series.map(function (point) { return int(point.net_cents) + Math.floor(int(point.net_credits) / Math.max(1, int(state.earnings.payout.credits_per_dollar)) * 100); });
    var max = Math.max.apply(Math, values.concat([1]));
    var width = 600;
    var height = 90;
    var points = values.map(function (value, index) {
      var x = values.length <= 1 ? width / 2 : index * width / (values.length - 1);
      var y = height - (value / max) * (height - 8) - 4;
      return [x.toFixed(1), y.toFixed(1)];
    });
    var line = points.map(function (point, index) { return (index ? "L" : "M") + point[0] + " " + point[1]; }).join(" ");
    var fill = points.length ? line + " L" + points[points.length - 1][0] + " " + height + " L" + points[0][0] + " " + height + " Z" : "";
    return '<svg class="st-sparkline" viewBox="0 0 600 90" role="img" aria-label="Net earnings over the selected period" preserveAspectRatio="none"><path class="st-spark-fill" d="' + fill + '"></path><path d="' + line + '"></path></svg>';
  }

  function earningCard(title, block, currency) {
    var gross = currency === "cash" ? int(block.gross_cents) : int(block.gross_credits);
    if (!gross) { return ""; }
    var fee = currency === "cash" ? int(block.fee_cents) : int(block.fee_credits);
    var net = currency === "cash" ? int(block.net_cents) : int(block.net_credits);
    var display = currency === "cash" ? formatCash : function (value) { return formatInt(value) + " credits"; };
    return '<div class="st-earning-card"><span>' + esc(title) + '</span><strong>' + display(net) + '</strong><div class="st-breakdown"><div><span>Gross</span><span>' + display(gross) + '</span></div><div><span>Platform fee</span><span>' + display(fee) + '</span></div>' + (int(block.orders) ? '<div><span>Orders</span><span>' + formatInt(block.orders) + "</span></div>" : "") + "</div></div>";
  }

  function renderPayouts() {
    var host = byId("payouts-content");
    var connect = state.connect;
    if (!connect || !connect.connected) {
      host.innerHTML = '<section class="st-panel"><div class="st-panel-heading"><div><p class="st-eyebrow">Stripe Connect</p><h2>Set up cash payouts</h2></div></div><p>Cash sales use Stripe Connect destination charges: Stripe collects from the buyer and pays your connected account directly. Chudware never holds that cash.</p><button class="btn primary" type="button" id="connect-start">Set up Stripe payouts</button><span class="st-submit-state" id="connect-state"></span></section>';
      byId("connect-start").addEventListener("click", startOnboarding);
      return;
    }
    var html = '<section class="st-panel"><div class="st-connect-state"><div><p class="st-eyebrow">Stripe Connect</p><h2>' + (connect.payouts_enabled ? "Cash payouts ready" : "Finish Stripe onboarding") + '</h2><p>Cash sales pay through Stripe directly. Account details remain with Stripe.</p><div class="st-connect-facts"><span class="st-status is-' + (connect.charges_enabled ? "verified" : "pending") + '">Charges ' + (connect.charges_enabled ? "enabled" : "pending") + '</span><span class="st-status is-' + (connect.payouts_enabled ? "verified" : "pending") + '">Payouts ' + (connect.payouts_enabled ? "enabled" : "pending") + "</span></div></div>" +
      (connect.needs_onboarding ? '<button class="btn primary" type="button" id="connect-start">Continue onboarding</button>' : "") + "</div></section>";
    if (state.earnings) {
      var period = state.earnings.period || {};
      var cards = earningCard("Cash net, last " + state.earnings.days + " days", period.cash || {}, "cash") + earningCard("Credit net, last " + state.earnings.days + " days", period.credits || {}, "credits");
      html += '<section class="st-panel"><div class="st-panel-heading"><div><h2>Earnings</h2><p class="muted">Fees and net are shown separately so the take-home is never a guess.</p></div><label class="st-field"><span class="small">Window</span><select id="earnings-days"><option value="30"' + (state.earnings.days === 30 ? " selected" : "") + '>30 days</option><option value="90"' + (state.earnings.days === 90 ? " selected" : "") + '>90 days</option><option value="365"' + (state.earnings.days === 365 ? " selected" : "") + ">1 year</option></select></label></div>" +
        (cards ? '<div class="st-earnings-grid">' + cards + "</div>" + sparkline(state.earnings.series || []) : '<div class="mk-empty st-empty"><h3>No earnings in this period</h3><p>Paid orders will appear here with gross, fee, and net values.</p></div>') + "</section>";
      var payout = state.earnings.payout || {};
      if (connect.payouts_enabled) {
        html += '<section class="st-panel"><div class="st-panel-heading"><div><h2>Cash out earned credits</h2><p class="muted">Credits are AI tokens and are spendable immediately. Cash-out is optional and each request is reviewed.</p></div></div><div class="st-payout-grid"><form class="st-form" id="payout-form"><label class="st-field"><span>Credits to cash out</span><input name="credits" type="number" step="1" min="' + int(payout.minimum_credits) + '" max="' + int(payout.balance_credits) + '" required><small>Minimum ' + formatInt(payout.minimum_credits) + " credits. Available: " + formatInt(payout.balance_credits) + ' credits.</small></label><div class="st-rule-box"><span class="st-rate" id="payout-conversion">Enter an amount to see the frozen conversion.</span><br>The conversion rate is frozen when you request it. An operator reviews the request before funds move.</div><button class="btn primary" type="submit"' + (int(payout.balance_credits) < int(payout.minimum_credits) ? " disabled" : "") + '>Request reviewed cash-out</button><span class="st-submit-state" id="payout-state"></span></form><div class="st-rule-box"><strong>Frozen rate</strong><p>' + formatInt(payout.credits_per_dollar) + ' credits = $1.00.</p><p>At the full available balance, the estimated conversion is ' + formatCash(payout.estimated_cents) + ".</p></div></div></section>";
      } else {
        html += '<section class="st-panel"><div class="mk-empty st-empty"><h3>Cash-out unlocks after Stripe onboarding</h3><p>Your earned credits remain available as AI tokens now. Complete payouts above before requesting a reviewed conversion to cash.</p></div></section>';
      }
    }
    host.innerHTML = html;
    if (byId("connect-start")) { byId("connect-start").addEventListener("click", startOnboarding); }
    if (byId("earnings-days")) { byId("earnings-days").addEventListener("change", function (event) { loadEarnings(int(event.target.value)); }); }
    if (byId("payout-form")) { bindPayoutForm(); }
  }

  async function startOnboarding() {
    var button = byId("connect-start");
    var output = byId("connect-state");
    button.disabled = true;
    setSubmitState(output, "Creating a secure Stripe onboarding link…", "");
    try {
      var result = await api("/api/studio/connect/onboard", jsonOptions("POST", {}));
      var url = safeHttpUrl(result.url);
      if (!url) { throw new Error("Stripe returned an invalid onboarding URL."); }
      window.location.assign(url);
    } catch (error) { setSubmitState(output, error.message, "error"); button.disabled = false; }
  }

  async function loadEarnings(days) {
    try {
      state.earnings = await api("/api/studio/earnings?days=" + encodeURIComponent(days || 90));
      renderPayouts();
    } catch (error) {
      byId("payouts-content").insertAdjacentHTML("beforeend", '<div class="st-notice is-error">' + esc(error.message) + "</div>");
    }
  }

  async function loadPayouts() {
    if (!state.isSeller) { return; }
    byId("payouts-content").innerHTML = '<div class="mk-skeleton st-skeleton"></div><div class="mk-skeleton st-skeleton"></div>';
    try {
      state.connect = await api("/api/studio/connect");
      state.earnings = null;
      renderPayouts();
      if (state.connect.connected) { await loadEarnings(90); }
    } catch (error) { byId("payouts-content").innerHTML = '<div class="mk-empty st-empty"><h2>Payout status could not load</h2><p>' + esc(error.message) + "</p></div>"; }
  }

  function bindPayoutForm() {
    var form = byId("payout-form");
    var input = form.querySelector("[name=credits]");
    var payout = state.earnings.payout;
    input.addEventListener("input", function () {
      var credits = int(input.value);
      var cents = Math.floor(credits * 100 / Math.max(1, int(payout.credits_per_dollar)));
      byId("payout-conversion").textContent = credits ? formatInt(credits) + " credits converts to " + formatCash(cents) + " at the frozen request rate." : "Enter an amount to see the frozen conversion.";
    });
    form.addEventListener("submit", async function (event) {
      event.preventDefault();
      var credits = int(input.value);
      var output = byId("payout-state");
      if (credits < int(payout.minimum_credits)) { setSubmitState(output, "The minimum is " + formatInt(payout.minimum_credits) + " credits.", "error"); return; }
      if (credits > int(payout.balance_credits)) { setSubmitState(output, "That exceeds the available credit balance.", "error"); return; }
      var button = form.querySelector("button[type=submit]");
      if (button.dataset.confirm !== "true") {
        button.dataset.confirm = "true";
        button.textContent = "Confirm reviewed request for " + formatInt(credits) + " credits";
        setSubmitState(output, "Confirm the exact credit amount. The conversion rate freezes when submitted.", "");
        return;
      }
      button.disabled = true;
      try {
        var result = await api("/api/studio/payouts", jsonOptions("POST", { credits: credits }));
        setSubmitState(output, "Request submitted for review: " + formatInt(result.credits) + " credits at " + formatCash(result.cents) + ".", "ok");
        await loadEarnings(state.earnings.days);
      } catch (error) { setSubmitState(output, error.message, "error"); button.disabled = false; }
    });
  }

  async function loadSettings() {
    var host = byId("settings-content");
    if (!state.isSeller) { return; }
    host.innerHTML = '<div class="mk-skeleton st-skeleton"></div>';
    try {
      var result = await api("/api/studio/seller");
      state.seller = result.seller;
      renderSettings();
    } catch (error) { host.innerHTML = '<div class="mk-empty st-empty"><h2>Settings could not load</h2><p>' + esc(error.message) + "</p></div>"; }
  }

  function renderSettings() {
    var seller = state.seller;
    var listingCount = int(state.overview && state.overview.stats && state.overview.stats.listings);
    var locked = listingCount > 0;
    byId("settings-content").innerHTML = '<div class="st-panel-heading"><div><h2>Public seller profile</h2><p class="muted">Visible on every marketplace listing.</p></div></div><form id="settings-form" class="st-form st-form-grid" novalidate>' +
      '<label class="st-field"><span>Handle</span><input name="handle" value="' + esc(seller.handle) + '" required minlength="2" maxlength="39" pattern="[a-z0-9][a-z0-9_-]{1,38}"' + (locked ? " disabled" : "") + ' aria-describedby="settings-handle-help"><small id="settings-handle-help">' + (locked ? "Immutable because this profile has listings. Stable handles keep shared marketplace links working." : "You can change this until the first listing is created.") + "</small></label>" +
      '<label class="st-field"><span>Display name</span><input name="display_name" value="' + esc(seller.display_name) + '" required maxlength="120"></label>' +
      '<label class="st-field st-field-wide"><span>Bio</span><textarea name="bio" maxlength="2000" rows="5">' + esc(seller.bio || "") + "</textarea></label>" +
      '<label class="st-field"><span>Website</span><input name="website" type="url" maxlength="500" value="' + esc(seller.website || "") + '"></label>' +
      '<label class="st-field"><span>Country</span><input name="country" maxlength="80" value="' + esc(seller.country || "") + '"></label>' +
      '<label class="st-field st-field-wide"><span>Organization ID <em>optional</em></span><input name="org_id" value="' + esc(seller.org_id || "") + '"></label>' +
      '<div class="st-form-actions st-field-wide"><button class="btn primary" type="submit">Save settings</button><span class="st-submit-state" id="settings-state"></span></div></form>';
    var form = byId("settings-form");
    if (!locked) {
      var handle = form.querySelector("[name=handle]");
      var feedback = byId("settings-handle-help");
      handle.dataset.available = handle.value === seller.handle ? "true" : "";
      handle.addEventListener("input", function () {
        if (handle.value.trim() === seller.handle) { handle.dataset.available = "true"; feedback.className = "is-ok"; feedback.textContent = "Current handle."; return; }
        scheduleHandleCheck(handle, feedback);
      });
    }
    form.addEventListener("submit", async function (event) {
      event.preventDefault();
      var output = byId("settings-state");
      if (!form.reportValidity()) { return; }
      var values = formValues(form);
      try {
        if (!locked && values.handle !== seller.handle && !(await ensureHandleAvailable(form.querySelector("[name=handle]"), byId("settings-handle-help")))) { setSubmitState(output, "Choose an available handle.", "error"); return; }
        var payload = { display_name: values.display_name, bio: values.bio, website: values.website, country: values.country, org_id: values.org_id || null };
        if (!locked) { payload.handle = values.handle; }
        setSubmitState(output, "Saving…", "");
        var result = await api("/api/studio/seller", jsonOptions("PATCH", payload));
        state.seller = result.seller;
        setSubmitState(output, "Settings saved.", "ok");
        await loadOverview();
      } catch (error) { setSubmitState(output, error.message, "error"); }
    });
  }

  function bindListings() {
    document.querySelectorAll("[data-list-status]").forEach(function (button) {
      button.addEventListener("click", function () {
        state.listingStatus = button.dataset.listStatus;
        state.listingCursor = null;
        document.querySelectorAll("[data-list-status]").forEach(function (other) { other.classList.toggle("is-active", other === button); });
        loadListings(false);
      });
    });
    byId("listing-list").addEventListener("click", function (event) {
      var button = event.target.closest("[data-list-action]");
      if (button) { listingAction(button); }
    });
    byId("listing-more").querySelector("button").addEventListener("click", function () { loadListings(true); });
  }

  async function boot() {
    bindEnrolment();
    bindListings();
    bindComposerShell();
    bindImports();
    window.addEventListener("hashchange", applyRoute);
    try {
      state.meta = await api("/api/marketplace/meta");
      var limits = metaLimits();
      if (!int(limits.max_asset_bytes) || !allowedExtensions().length) {
        notice("Marketplace upload limits are unavailable; file authoring is disabled until the page is reloaded.", "error");
      }
    } catch (error) {
      notice("Marketplace metadata could not load: " + error.message, "error");
    }
    await loadOverview();
    applyRoute();
  }

  document.addEventListener("DOMContentLoaded", boot);
}());
